  const extension = createExtension({
    name: 'Safety and Productivity Booster Pack',
    version: '1.0',
    icons: ['assets/icon-192x192.png'],
    badge: { visible: true }
  });

  extension.onInstalled.addListener((e) => {
    e.waitUntil(
      new Promise((resolve, reject) => {
        // Initialize local storage for temporary captures
        const captureSession = {};
        const captureHistory = [];
        captureSession.lastSessionId = Date.now().toString();
        captureHistory.push(captureSession);
        // Save to localStorage for auto-start
        localStorage.setItem('safeCaptureSession', JSON.stringify(captureSession));
        resolve();
      })
    );
  });

  extension.onActivated.addListener((e) => {
    e.request.enable();
  });

  extension.onCommand.addListener((cmd, param) => {
    if (cmd === 'capture-start') {
      const sessionId = Date.now().toString();
      const session = {
        id: sessionId,
        images: [],
        videos: [],
        audio: [],
        timestamps: [],
        viewport: {}
      };
      captureHistory.push(session);
      localStorage.setItem('safeCaptureSession', JSON.stringify(session));
      return Promise.resolve(true);
    }
    return Promise.resolve(false);
  });

  extension.onRemoved.addListener((e) => {
    localStorage.removeItem('safeCaptureSession');
  });

  extension.onChanged.addListener((e) => {
    console.log('Capture events detected:', e.detail.changes);
  });

  extension.onMessage.addListener((msg) => {
    // Handle messages from the main window
    console.log('Extension received:', msg);
  });
}
